function output(userData, context) {

  if (userData.is_coupon_code) {
    if(!userData.female_under_50){
      context.setUserData({ method: 'combination'} );
    } else {
      context.setUserData({ method_fem: 'combination'} );
    }
    return;
  }

  if (userData.consult !== true) {
    const methodKey = userData.female_under_50 ? "method_fem" : "method";

    context.setUserData({ [methodKey]: userData.method_options[0].key });

    return;
  }

  if (!userData.female_under_50) {
    if (!userData.method) {
      if (
        userData.how_committed_to_hair_loss === "results_as_quickly_as_possible"
      ) {
        console.log("setting method to BUNDLE");
        context.setUserData({ method: "combination" });
      } else {
        if (userData.preferred_method_of_medication === "oral") {
          console.log("setting method to capsule");
          setTimeout(() => {
            console.log("setting method to capsule");
            context.setUserData({ method: "capsule_1" });
          }, 300);
        } else {
          context.setUserData({ method: "scalp" });
          console.log("method:", userData.method);
        }
      }
    }
  } else {
    if (!userData.method_fem) {
      if (
        userData.how_committed_to_hair_loss === "results_as_quickly_as_possible"
      ) {
        console.log("setting method to BUNDLE");
        context.setUserData({ method_fem: "combination" });
      } else {
        if (userData.preferred_method_of_medication === "oral") {
          setTimeout(() => {
            console.log("setting method to capsule not fem under 50");
            context.setUserData({ method_fem: "capsule_1" });
          }, 300);
        } else {
          context.setUserData({ method_fem: "scalp" });
          console.log("method_fem:", userData.method_fem);
        }
      }
    }
  }
}

