      console.log("Unique session ID:", sessionId);

      // Set the necessary cookies (age, dob, email, unique_id) for root domain
      const domain = cookie_domain;

      // Example values from userData, replace with actual user data
      const age = userData.age || 25; // Example, you can set this from userData
      // const dob = userData.date_of_birth || "1990-01-01"; // Example date of birth
      const dob = userData.date_of_birth_formatted || "1990-01-01"; // Example date of birth
      const email = userData.email || "user@example.com"; // Example email
      const uniqueId = userData.unique_id || unique_id; // Example unique_id, either from userData or sessionId

      const genderAnswerMap = {
        male: 'm',
        female: 'f'
      }

      const gender = genderAnswerMap[userData.sex_at_birth];

      // Set the cookies for age, dob, email, gender, and unique_id
      hhSetCookie("age", age, domain);
      hhSetCookie("dob", dob, domain);
      hhSetCookie("email", email, domain);
      hhSetCookie("gender", gender, domain);
      hhSetCookie("unique_id", uniqueId, domain);

      // URL parameters needed for checkout redirection
      const encodedEmail = btoa(userData.email); // Base64 encode the email
      const productIds = userData.product_ids;
      const couponCode = new URLSearchParams(window.location.search).get('coupon'); // Example coupon, replace if needed

      const phone = userData.phone;

      // Determine the base URL based on the hostname
      let baseUrl = window.location.hostname.includes("form.happyhead.com")
        ? "https://my.happyhead.com/hh-checkout/"
        : window.location.hostname.includes("form.dev.happyhead.com")
          ? "http://my.dev.happyhead.com/hh-checkout/"
          : "http://my.staging.happyhead.com/hh-checkout/"

      // Prepare the checkout URL with the necessary query parameters
      let checkoutUrl;

      if (userData.consult) {
        if (userData.is_include_pid) {
          checkoutUrl = `${baseUrl}?be=${encodedEmail}&unique_id=${uniqueId}&aero-add-to-checkout=${userData.consult_pid}%2C${userData.is_include_pid}`
        } else {
          checkoutUrl = `${baseUrl}?be=${encodedEmail}&unique_id=${uniqueId}&aero-add-to-checkout=${userData.consult_pid}`
        }
      } else {
        if (userData.is_include_pid) {
          checkoutUrl = `${baseUrl}?be=${encodedEmail}&unique_id=${uniqueId}&aero-add-to-checkout=${productIds}%2C${userData.is_include_pid}`;
        } else {
          checkoutUrl = `${baseUrl}?be=${encodedEmail}&unique_id=${uniqueId}&aero-add-to-checkout=${productIds}`;
        }
      }

      const isMaleOrFemaleOver50 = userData.sex_at_birth === 'male' || userData.age_range_female === 'over_50';

      if (couponCode) {
        const lowerCaseCode = couponCode.toLowerCase();

        if (userData.is_coupon_code && !isMaleOrFemaleOver50) {
          checkoutUrl += `&aero-coupons=womenstarterkit%2C${lowerCaseCode}`;
        } else {
          checkoutUrl += `&aero-coupons=${lowerCaseCode}`;
        }
      }

      // If a phone number is provided, add it to the URL
      if (phone) {
        const formatUSPhoneNumber = (phoneNumber) => {
          // remove all non-numeric characters except the '+' sign
          let cleanedNumber = phoneNumber.replace(/[^\d+]/g, '');

          // check if the number already has the country code '+1'
          if (!cleanedNumber.startsWith('+1')) {
            cleanedNumber = '+1' + cleanedNumber.replace(/^\+?1?/, '');
          }

          return cleanedNumber;
        }

        checkoutUrl += `&bp=${btoa(formatUSPhoneNumber(phone))}`;
      }

      console.log("checkoutUrl: ", checkoutUrl)
      // Get the current URL parameters (excluding the path)
      const currentUrlParams = new URLSearchParams(window.location.search);

      // Add all current URL parameters to the checkout URL (if any)
      currentUrlParams.forEach((value, key) => {
        // Exclude the parameters that are already included in the checkoutUrl to avoid duplicates
        if (!checkoutUrl.includes(key)) {
          checkoutUrl += `&${key}=${value}`;
        }
      });

      if (sessionId) {
        checkoutUrl += `&hhsid=${encodeURIComponent(sessionId)}`;
      }

      console.log("Redirect to checkout URL:", checkoutUrl);

      // if (userData.jf2 && userData.jf2 === "var2") {
      //   context.setUserData({ user_reached_the_checkout_page: true });
      //   window.location.href = checkoutUrl;
      //   return;
      // }

      // Output the final checkout URL
      context.setUserData({
        redirect_url: checkoutUrl,
        show_checkout_next: true,
      });
      setTimeout(() => {
        context.setUserData({ show_checkout_next: true });
      }, 3000);
    })
    .catch((error) => {
      console.error("Error:", error);
    });
}

