function output(userData, { setUserData }) {
  let container = ".ComponentKey-slider_inner";
  if (userData.female_under_50 === true) {
    container = ".ComponentKey-slider_inner_fem";
  }

  findContainer(container, draggableSlider);

  function draggableSlider(scrollable) {
  let isDown = false;
  let startX, lastX, startY, lastY;

  scrollable.addEventListener("mousedown", (e) => {
    isDown = true;
    startX = e.pageX;
    lastX = e.pageX;
    startY = e.pageY;
    lastY = e.pageY;
  });

  scrollable.addEventListener("mouseleave", () => {
    isDown = false;
  });

  scrollable.addEventListener("mouseup", () => {
    isDown = false;
    const deltaX = lastX - startX;
    const deltaY = lastY - startY;

    // If the vertical movement is greater than the horizontal one, we do nothing.
    if (Math.abs(deltaY) > Math.abs(deltaX)) {
      return;
    }

    // If the horizontal movement is greater, we execute the slider logic.
    handleSlideChange(lastX - startX);
  });

  scrollable.addEventListener("mousemove", (e) => {
    e.preventDefault();
    if (isDown) {
      lastX = e.pageX;
      lastY = e.pageY;
    }
  });

  scrollable.addEventListener("touchstart", (e) => {
    const touch = e.touches[0];
    startX = touch.pageX;
    lastX = touch.pageX;
    startY = touch.pageY;
    lastY = touch.pageY;
  });

  scrollable.addEventListener("touchmove", (e) => {
    const touch = e.touches[0];
    lastX = touch.pageX;
    lastY = touch.pageY;
  });

  scrollable.addEventListener("touchend", () => {
    const deltaX = lastX - startX;
    const deltaY = lastY - startY;

    // If the vertical movement is greater than the horizontal one, we do nothing (allowing vertical scrolling).
    if (Math.abs(deltaY) > Math.abs(deltaX)) {
      return;
    }

    // If the horizontal movement is greater, we execute the slider logic.
    handleSlideChange(deltaX);
  });

  function handleSlideChange(deltaX) {
    let method = userData.female_under_50
      ? window.Savvy.getUserData("flow_d02099468c5fg664dh31b7cg").method_fem
      : window.Savvy.getUserData("flow_d02099468c5fg664dh31b7cg").method;

    let array = userData.consult === true
