function findContainer(selector, callback) {
  let attempts = 0;
  const maxAttempts = 50;
  const intervalTime = 100; // time in milliseconds between attempts
  const intervalId = setInterval(() => {
    attempts++;
    const element = document.querySelector(selector);
    if (element) {
      clearInterval(intervalId);
      callback(element);
    } else if (attempts >= maxAttempts) {
      clearInterval(intervalId);
      console.error(`Draggable product carousel - PRP page load: Element not found after ${maxAttempts} attempts.`);
    }
  }, intervalTime);
}

