function removeAeroCouponsFromRedirectUrl(redirectUrl) {
  const queryStart = redirectUrl.indexOf('?');
  if (queryStart === -1) return redirectUrl;

  const base = redirectUrl.slice(0, queryStart);
  const query = redirectUrl.slice(queryStart + 1);
  const remainingParams = query
    .split('&')
    .filter((part) => part && !part.toLowerCase().startsWith('aero-coupons='));

  if (!remainingParams.length) return base;
  return `${base}?${remainingParams.join('&')}`;
}

function resolveDermUpsellRedirectUrl(redirectUrl, userData) {
  if (!redirectUrl) return redirectUrl;

  const upgradePath = (
    userData.upgrade_path ||
    new URLSearchParams(window.location.search).get('upgrade') ||
    ''
  )
    .toString()
    .trim()
    .toLowerCase();

  if (upgradePath !== 'derm') return redirectUrl;

  // Only CHOOSE TOPICAL + DERMAROLLER keeps the derm bundle coupon on checkout.
  if (userData.include_dermaroller_upgrade === true) return redirectUrl;

  return removeAeroCouponsFromRedirectUrl(redirectUrl);
}

