function output(userData, context) {
  if (!userData.redirect_url) return;

  const url = userData.redirect_url;

  const newMainPid = userData.consult ? userData.consult_pid : userData.product_ids;

  const updatedUrl = url.replace(
    /(aero-add-to-checkout=)([^&]*)/,
    (_, prefix, value) => {
      const parts = value.split('%2C');

      // If include_pid exists, it is ALWAYS the last element
      if (userData.is_include_pid) {
        const includePid = parts[parts.length - 1];
        return `${prefix}${newMainPid}%2C${includePid}`;
      }

      // No include_pid → replace entirely
      return `${prefix}${newMainPid}`;
    }
  );

  console.log('Updated checkout URL after plan change:', updatedUrl);

  context.setUserData({
    redirect_url: updatedUrl
  });
}

