function output(userData, { setUserData }) {
  if (!userData?.phone) return;

  setUserData({
    phone_registered_to_request_callback: undefined,
    is_requesting_a_callback: true,
    is_request_a_callback_error: false
  })

  const formatUSPhoneNumber = (phoneNumber) => {
    // remove all non-numeric characters except the '+' sign
    let cleanedNumber = phoneNumber.replace(/[^\d+]/g, '');

    // check if the number already has the country code '+1'
    if (!cleanedNumber.startsWith('+1')) {
      cleanedNumber = '+1' + cleanedNumber.replace(/^\+?1?/, '');
    }

    return cleanedNumber;
  }

  const isProduction = window.location.hostname.includes("form.happyhead.com");

  const environment = isProduction
    ? "prod"
    : "staging";

  const zendeskToken = isProduction ? 'Basic {{cred_fhvasc3p4gfb}}' : 'Basic {{cred_3x1ysfz1j06o}}'

  const url = "https://happyhead.zendesk.com/api/v2/channels/voice/callback_requests";

  fetch(`https://request.embeddables.com/?url=${encodeURIComponent(url)}`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Authorization": zendeskToken,
      'X-Environment': environment,
      'X-Project-ID': "pr_wI2KhdvowjwMheSt"
    },
    body: JSON.stringify({
      "callback_request": {
        "phone_number_id": 29399058783127,
        "requester_phone_number": formatUSPhoneNumber(userData?.phone)
      }
    })
  })
    .then((response) => {
      if (response.status !== 201) {
        throw new Error(`Response status: ${response.status}`);
      }
    })
    .then(() => {
      setTimeout(() => {
        setUserData({
          phone_registered_to_request_callback: userData?.phone,
          is_requesting_a_callback: false,
          show_phone_section: false,
          show_phone_toast: true,
          requested_a_callback: true
        });

        setTimeout(() => {
          const currentScroll = window.scrollY;
          let startTime = null;

          function smoothScroll(timestamp) {
            console.log("Request a callback")
            if (!startTime) startTime = timestamp;
            const progress = timestamp - startTime;
            const scrollTo = Math.max(currentScroll - (currentScroll * progress) / 1000, 0);

            window.scrollTo(0, scrollTo);

            if (scrollTo > 0) {
              requestAnimationFrame(smoothScroll);
            }
          }

          if (userData.current_page_key !== "category_lp_v2") requestAnimationFrame(smoothScroll);
        }, 200);
      }, 500);
    })
    .catch((error) => {
      console.log("Error requesting a callback");
      console.error(error.message);
      setTimeout(() => {
        setUserData({
          phone_registered_to_request_callback: undefined,
          is_requesting_a_callback: false,
          requested_a_callback: false,
          is_request_a_callback_error: true,
          request_a_callback_error_message: "Could not create a callback request call."
        });
      }, 500);
    });
}

function output(userData, { setUserData }) {
  if (userData?.show_phone_section) {
    setUserData({ show_phone_section: false});
    return;
  }

  setUserData({
    show_phone_section: true,
    show_phone_toast: false
  });

  setTimeout(() => {
    const totalHeight = document.documentElement.scrollHeight;
    const currentScroll = window.scrollY;
    const distance = totalHeight - currentScroll;
    let startTime = null;

    function smoothScroll(timestamp) {
      console.log("Set show_phone_section")
      if (!startTime) startTime = timestamp;
      const progress = timestamp - startTime;
      const scrollTo = Math.min(currentScroll + (distance * progress) / 1000, totalHeight);

      window.scrollTo(0, scrollTo);

      if (scrollTo < totalHeight) {
        requestAnimationFrame(smoothScroll);
      }
    }

    requestAnimationFrame(smoothScroll);
  }, 200);
}

