function output(userData, context) {
  const isWithinTimeRange = () => {
    const now = new Date();

    const pstHour = now.getUTCHours() - 8;
    const dayOfWeek = now.getUTCDay();

    const startHour = 6;
    const endHour = 17;

    if (dayOfWeek === 0 || dayOfWeek === 6) {
      return false;
    }

    return pstHour >= startHour && pstHour < endHour;
  };

  context.setUserData({ agents_available: isWithinTimeRange() });
}

