          {
            key: 'combination',
            text: 'Spironolactone & Minoxidil<sup>RX</sup>',
            imageUrl: 'https://assets.embeddables.com/Frame11911_9129211232241023.png',
            // sku: 'SUPERCAP-SPIR-1-TOP-MIN6-1',
            description: 'Topical<sup>Rx</sup> Solution + Oral<sup>Rx</sup> SuperCapsule<sup>TM</sup> Bundle',
            triggerEvent: "no-action"
          }
        }
      };

      const isRedesignedLFunnel = userData.l === false || userData.l === 'false';
      const femaleUnder50 =
        userData.female_under_50 === true ||
        (isRedesignedLFunnel && userData.gender_and_age === 'female_under_50');

      const cardsVariants = getPrpV2Cards(userData.upgrade_path);

      const getCardsForUser = (gender, femaleUnder50) => {
        const result = [];

        Object.keys(cardsVariants).forEach(cardType => {
          const variants = cardsVariants[cardType];
          let selectedVariant;

          if (gender === 'male') {
            selectedVariant = variants.male_and_female_over_50;
          } else if (gender === 'female') {
            if (femaleUnder50) {
              selectedVariant = variants.female_under_50;

            } else {
              selectedVariant = variants.male_and_female_over_50;
            }
          }

          if (selectedVariant) {
            result.push(selectedVariant);
          }
        });

        return result;
      };


      const cards = getCardsForUser(userData.sex_at_birth, femaleUnder50);

      const filterProductsByResponseUpdated = (data) => {
        return cards.map(item => {

          // ---------- SCALP ----------
          if (item.key === 'scalp') {
            // Looking for the product whose SKU includes 'TOP'
            const product = data.flat().find(p => p.sku.includes('TOP'));
            const subscriptionId = product?.woocommerceSubscriptionProductId;
            const oneTimeId = product?.woocommerceSimpleProductId;

            return {
              ...item,
              woocommerceId: subscriptionId != null ? String(subscriptionId) : undefined,
              woocommerceIds: {
                subscription: subscriptionId != null ? String(subscriptionId) : undefined,
                one_time: oneTimeId != null ? String(oneTimeId) : undefined,
              }
            };
          }

          // ---------- CAPSULE ----------
          if (item.key === 'capsule') {
            // Looking for the product whose SKU includes "SUPERCAP"
            const product = data.flat().find(p => p.sku.includes('SUPERCAP'));
            const subscriptionId = product?.woocommerceSubscriptionProductId;
            const oneTimeId = product?.woocommerceSimpleProductId;
            return {
              ...item,
              woocommerceId: subscriptionId != null ? String(subscriptionId) : undefined,
              woocommerceIds: {
                subscription: subscriptionId != null ? String(subscriptionId) : undefined,
                one_time: oneTimeId != null ? String(oneTimeId) : undefined,
              }
            };
          }

          // ---------- BUNDLE ----------
          if (item.key === 'combination') {
            // Looking for the array that has length = 2
            const bundle = data.find(group => group.length === 2);
            const subscriptionIds = bundle
              ? bundle.map(p => p.woocommerceSubscriptionProductId).join('%2C')
              : undefined;

            const oneTimeIds = bundle
              ? bundle.map(p => p.woocommerceSimpleProductId).join('%2C')
              : undefined;
            return {
              ...item,
              woocommerceId: subscriptionIds,
              woocommerceIds: {
                subscription: subscriptionIds,
                one_time: oneTimeIds,
              }
            };
          }

          return item;
        });
      };

      const orderByApiResponse = (array) => {
        const keyOrder = data.map(group => {
          if (group.length === 2) return 'combination';
          const sku = group[0]?.sku || '';
          if (sku.includes('TOP')) return 'scalp';
          if (sku.includes('SUPERCAP')) return 'capsule';
          return null;
        }).filter(Boolean);

        return keyOrder.map(key => array.find(item => item.key === key)).filter(Boolean);
      };

      const reorderBundleFirst = (options) => {
        const bundle = options.find(item => item.key === 'combination');
        if (!bundle) return options;

        return [bundle, ...options.filter(item => item.key !== 'combination')];
      };

      const cardsWithPids = filterProductsByResponseUpdated(data);

      const preferenceMethodKeys = {
        oral: ['combination', 'capsule'],
        topical: ['combination', 'scalp'],
        unsure_no_preference: ['combination', 'scalp'],
      };

      const allowedMethodKeys =
        preferenceMethodKeys[userData.preferred_method_of_medication] ??
        preferenceMethodKeys.unsure_no_preference;

      const filterByPreference = (options) =>
        options.filter((item) => allowedMethodKeys.includes(item.key));

      const method_options = filterByPreference(
        reorderBundleFirst(orderByApiResponse(cardsWithPids))
      );

      const newMethodOptions = userData.is_coupon_code ? method_options.filter(item => item.key === 'combination') : method_options;

      const tabOptions = [
        {
          key: 'scalp',
          text: 'Apply on Scalp',
          triggerEvent: "no-action"
        },
        {
          key: 'capsule',
          text: 'Take as Capsule',
          triggerEvent: "no-action"
        },
        {
          key: 'combination',
          text: 'Combination',
          triggerEvent: "no-action"
        }];

