        key: 'scalp',
        text: '',
        triggerEvent: "no-action"
      },
      {
        key: 'capsule',
        text: '',
        triggerEvent: "no-action"
      },
      {
        key: 'combination',
        text: '',
        triggerEvent: "no-action"
      }];

      const method_carousel_buttons = filterByPreference(orderByApiResponse(carouselButtons));

      context.setUserData({
        method_options: newMethodOptions,
