  function moveItemsContinuously() {
    const maxScrollLeft = scrollContainer.scrollWidth - scrollContainer.clientWidth;

    // If the container has reached the end of the scroll
    if (scrollContainer.scrollLeft >= maxScrollLeft - 5) {
      const firstItem = ingredientsContainer.firstElementChild; // Get the first item
