    stopAutoScroll(); // Clear any existing interval
    autoScrollInterval = setInterval(() => {
      scrollContainer.scrollLeft += 1.2; // Adjust the speed by changing the value
      moveItemsContinuously(); // Move the elements to create an infinite effect
    }, 20); // Adjust the interval for the speed
  }

  // Function to stop the autoscroll
  function stopAutoScroll() {
    clearInterval(autoScrollInterval);
  }

  // Mouse-based dragging
  scrollContainer.addEventListener('mousedown', (e) => {
    isDragging = true;
    stopAutoScroll(); // Pause autoscroll
    startX = e.pageX - scrollContainer.offsetLeft;
