function output() {
    const testimonialsCarousel = document.querySelector(".ComponentTag-outer_container");
    const nextButton = document.querySelector(".ComponentTag-carousel_next_button");
    const backButton = document.querySelector(".ComponentTag-carousel_back_button");

    if (!testimonialsCarousel || !nextButton || !backButton) return;

    const enabledColor = "#242B3380";
    const disabledColor = "#242B334D";

    const setButtonColors = (nextColor, backColor) => {
        nextButton.style.backgroundColor = nextColor;
        backButton.style.backgroundColor = backColor;
    }

    const handleScroll = () => {
        const { scrollLeft, clientWidth, scrollWidth } = testimonialsCarousel;
        const isAtStart = scrollLeft === 0;
        const isAtEnd = scrollLeft + clientWidth >= scrollWidth;

        if (isAtStart) {
            setButtonColors(enabledColor, disabledColor);
        } else if (isAtEnd) {
