function output(userData, context) {
  if (!userData.consult) return;

  if (userData.is_dandruff_treatment) {
    const currentUrl = window.location.href;
    const url = new URL(currentUrl);
    const searchParams = url.searchParams;

    const pid = searchParams.get("pid");

    context.setUserData({
      consult_pid: encodeURIComponent(pid),
      is_pid_updated: false
    });

    return;
  }

  context.setUserData({ is_loading_prod_recommendation: true });

  const isDev = window.location.origin.includes('form.dev.happyhead.com');

  const environment = userData.is_production_environment
    ? 'prod'
    : isDev
      ? 'dev'
      : 'staging';

  const apiKey = userData.is_production_environment
    ? '{{cred_kfd7xhzotpc5}}'
    : isDev
      ? '{{cred_3rime6wfwczk}}'
      : '{{cred_m43j8wggfivx}}';

  let url = userData.is_production_environment
    ? 'https://api.happyhead.com/middleware/product-recommendation'
    : isDev
      ? 'https://api.dev.happyhead.com/middleware/product-recommendation'
      : 'https://api.staging.happyhead.com/middleware/product-recommendation';

  let formatted_pid;

  if (!userData.pid) {
    formatted_pid = [];
  } else if (typeof userData.pid === 'number') {
    formatted_pid = [userData.pid];
  } else {
    formatted_pid = userData.pid.toString().split(',').map(num => parseInt(num, 10)).filter(Number.isInteger);
  }

  const options = {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json; charset=utf-8',
      'x-api-key': apiKey,
      'X-Environment': environment,
      'X-Project-ID': "pr_wI2KhdvowjwMheSt"
    },
    body: JSON.stringify({
      dateOfBirth: userData.date_of_birth_formatted,
      userChosenPids: formatted_pid,
      userPreferredMethods: ['Oral', 'Topical'],
      gender:
        userData.sex_at_birth.charAt(0).toUpperCase() +
        userData.sex_at_birth.slice(1),
    }),
  };

  fetch(`https://request.embeddables.com/?url=${encodeURIComponent(url)}`, options)
    .then((response) => {
      if (!response.ok) {
        throw new Error(`Response status: ${response.status}`);
      }
      return response.json();
    })
    .then((data) => {
      // console.log(data);

      if (data && data.length === 0) {
        context.setUserData({
          consult_pid: userData.pid,
          is_pid_updated: false
        });

        return;
      }

      const getFirstPidsOld = (data) => {
        if (!Array.isArray(data) || data.length === 0 || !Array.isArray(data[0])) {
          return '';
        }

        const firstElement = data[0];
        if (!Array.isArray(firstElement) || firstElement.length === 0) {
          return '';
        }

        const pids = firstElement
          .filter(item => item.hasOwnProperty("woocommerceId"))
          .map(item => item.woocommerceId.toString());

        return pids.length > 0 ? pids.join("%2C") : '';
      }

      const getFirstPids = (data) => {
        if (!Array.isArray(data) || !Array.isArray(data[0]) || data[0].length === 0) {
          return null;
        }

        const firstElement = data[0];

        const subscriptionPids = firstElement
          .filter(item => item?.woocommerceSubscriptionProductId != null)
          .map(item => item.woocommerceSubscriptionProductId.toString())
          .join('%2C');

        const oneTimePids = firstElement
          .filter(item => item?.woocommerceSimpleProductId != null)
          .map(item => item.woocommerceSimpleProductId.toString())
          .join('%2C');

        return {
          subscription: subscriptionPids || '',
          onetime: oneTimePids || ''
        };
      }

      const pidSet = userData.is_one_time_flow ? getFirstPids(data) : getFirstPidsOld(data);

      const newPid = userData.is_one_time_flow ? pidSet?.subscription || '' : pidSet;

      const hasPidChanged = () => {
        if (!userData.pid) return false;

        const parsePid = (pid, separator) =>
          pid.toString()
            .split(separator)
            .map(num => parseInt(num, 10))
            .filter(Number.isInteger);

        if (typeof userData.pid === "number") {
          return userData.pid.toString() !== newPid;
        }

        const urlPids = parsePid(userData.pid, ",");
        const apiPids = parsePid(newPid, "%2C");

        const areArraysDifferent = (arr1, arr2) =>
          arr1.length !== arr2.length || arr1.some((val, i) => val !== arr2[i]);

        return areArraysDifferent(urlPids, apiPids);
      };

      context.setUserData({
        consult_pid: newPid,
        consult_pid_subscription: pidSet?.subscription,
        consult_pid_onetime: pidSet?.onetime,
        is_pid_updated: hasPidChanged()
      })
    })
    .catch((error) => {
      console.error(error.message);
      context.setUserData({ is_loading_prod_recommendation: false });
    });
}

