          let cookie_domain = userData.is_production_environment
            ? ".happyhead.com"
            : isDev
              ? ".dev.happyhead.com"
              : ".staging.happyhead.com";
          const hhSetCookie = (name, value, domain = cookie_domain) => {
            const maxAge = 400 * 24 * 60 * 60; // 400 days
            document.cookie = `${name}=${value}; max-age=${maxAge}; domain=${domain}; path=/; Secure; SameSite=Strict`;
          };

          // Set the necessary cookies (age, dob, email, unique_id) for root domain
          const domain = cookie_domain;

          const genderAnswerMap = {
            male: 'm',
            female: 'f'
          }

          const gender = genderAnswerMap[userData.sex_at_birth];

          // Set the cookie for gender
          hhSetCookie("gender", gender, domain);

          if (!response.ok) {
            context.setUserData({ gender_submitted_event_error_2: response.status });
            throw new Error(`Response status: ${response.status}`);
          }
        })
        .catch((error) => {
          console.log("Catching error");
