function triggerEvent({ getUserData, setUserData, eventType }) {
  try {
    const isProduction = window.location.hostname.includes("form.happyhead.com");
    const isDev = window.location.origin.includes("form.dev.happyhead.com");
    const apiKey = isProduction
      ? "f8d44ba7-2d6a-4aa6-aabf-811f85f11770"
      : isDev
        ? "{{cred_3rime6wfwczk}}"
        : "secret";
    let url = isProduction
      ? "https://api.happyhead.com/middleware/analytic-events/"
      : isDev
        ? "https://api.dev.happyhead.com/middleware/analytic-events/"
        : "https://api.staging.happyhead.com/middleware/analytic-events/";

    // Helper function to get cookie by name
    function getCookieByName(name) {
      const cookies = document.cookie.split(";");
      for (let cookie of cookies) {
        cookie = cookie.trim();
        if (cookie.startsWith(name + "=")) {
          return cookie.substring(name.length + 1);
        }
      }
      return null;
    }

    // Helper function to get query parameters from the URL
    const hhGetQueryParam = (key) => {
      const urlParams = new URLSearchParams(window.location.search);
      return urlParams.get(key);
    };

    // Helper function to send a POST request
    const hhSendRequest = (id, eventType, eventProperties, userProperties) => {
      const options = {
        method: "POST",
        headers: {
          "Content-Type": "application/json; charset=utf-8",
          "x-api-key": apiKey,
        },
        body: JSON.stringify({
          eventType,
          deviceId: id ? id.toString() : null,
          userAgent: navigator.userAgent,
          eventProperties,
          userProperties,
        }),
      };

      // Perform synchronous fetch
      fetch(url, options)
        .then((response) => {
          // console.log("Entering try");
          if (!response.ok) {
            setUserData({ [`${eventType.toLowerCase().replace(/\s+/g, '_')}_event_error_2`]: response.status })
            throw new Error(`Response status: ${response.status}`);
          }
        })
        .catch((error) => {
          // console.log("Catching error");
          console.error(JSON.stringify(error));
          setUserData({ [`${eventType.toLowerCase().replace(/\s+/g, '_')}_event_error_3`]: JSON.stringify(error) })
        });
    };

    // Generate a new session ID or retrieve it from cookies
    const sessionId = getCookieByName("hh_session_id");

    const userData = getUserData();
    const utm_source = userData.utm_source;
    const initial_utm_source = userData.initial_utm_source;
    const ip_address = userData.ip_address;
    const current_page_key = userData.current_page_key;
    const product_ids = userData.product_ids;

    const pageTitle = current_page_key === 'emotional_survey_lp' ? 'Top LP3' : current_page_key;

    // Function to replace '%2C' with '-' in products that are a bundle
    const processProductIds = (productId) => {
      if (!productId) return productId;

      if (typeof productId !== 'string') return productId;

      return productId.replace(/%2C/g, '-');
    }

    // Event Properties
    const eventProperties = {
      "PIDs": processProductIds(product_ids) || "",
      "Page URL": (typeof location !== "undefined" && location.href) || "",
      "Referrer": (typeof document !== "undefined" && document.referrer) || "",
      "Page Path": window.location.pathname,
      "Unique Ids": {
        _fbp: hhGetQueryParam("_fbp") || getCookieByName("_fbp") || null,
