        _vwo_uuid: hhGetQueryParam("_vwo_uuid") || getCookieByName("_vwo_uuid") || null,
        _vwo_uuid_v2: hhGetQueryParam("_vwo_uuid_v2") || getCookieByName("_vwo_uuid_v2") || null,
        _rdt_cid: hhGetQueryParam("_rdt_cid") || getCookieByName("_rdt_cid") || null,
        _rdt_uuid: hhGetQueryParam("_rdt_uuid") || getCookieByName("_rdt_uuid") || null,
        ttclid: hhGetQueryParam('ttclid') || getCookieByName('ttclid') || null,
        _ttp: hhGetQueryParam('_ttp') || getCookieByName('_ttp') || null,
      },
      "Page Title": pageTitle,
      "Page Domain": window.location.hostname,
      "Event Source": "Embeddables",
      "Referring Domain": "www2.happyhead.com",
    };

    // User Properties
    const userProperties = {
      "unique_ids": {
        _fbp: hhGetQueryParam("_fbp") || getCookieByName("_fbp") || null,
        _fbc: hhGetQueryParam("_fbc") || getCookieByName("_fbc") || null,
        _gid: hhGetQueryParam("_gid") || getCookieByName("_gid") || null,
        __kla_id: hhGetQueryParam("__kla_id") || getCookieByName("__kla_id") || null,
        _vwo_uuid: hhGetQueryParam("_vwo_uuid") || getCookieByName("_vwo_uuid") || null,
        _vwo_uuid_v2: hhGetQueryParam("_vwo_uuid_v2") || getCookieByName("_vwo_uuid_v2") || null,
        _rdt_cid: hhGetQueryParam("_rdt_cid") || getCookieByName("_rdt_cid") || null,
        _rdt_uuid: hhGetQueryParam("_rdt_uuid") || getCookieByName("_rdt_uuid") || null,
