      "initial_utm_source": initial_utm_source || getCookieByName("initial_utm_source") || null,
      "utm_term": hhGetQueryParam("utm_term") || getCookieByName("utm_term") || null,
      "utm_medium": hhGetQueryParam("utm_medium") || getCookieByName("utm_medium") || null,
