function output(userData) {
  let currentIndex = 0;  // 0 for banner_1, 1 for banner_2
  let banners = document.querySelectorAll('.Flow-EntireFlow.id-flow_d02099468c5fg664dh31b7cg .Flow-Component.ComponentTag-bot_lp_banner_styles');

  // let allBanners = document.querySelectorAll('.Flow-EntireFlow.id-flow_d02099468c5fg664dh31b7cg .Flow-Component.ComponentTag-banner_styles');

  // const allBannersArray = Array.from(allBanners);

  // const banners = allBannersArray.slice(-2);

  let isPaused = false; // Track whether the carousel is paused or not
  if (window.hhInterval) {
    clearInterval(window.hhInterval);
  }

  const rotateCarousel = () => {
      if (isPaused) return;  // Skip rotation if paused

      // Move the current banner out to the left
      banners[currentIndex].style.transform = 'translateX(-100%)';

      // Switch to the next banner
      currentIndex = (currentIndex + 1) % banners.length;

      // Trigger the transition to make it slide in from the right
      banners[currentIndex].style.transform = 'translateX(0)';
      banners[currentIndex].style.zIndex = '9999';

      setTimeout(() => {
          banners[currentIndex === 1 ? 0 : 1].style.transform = 'translateX(100%)';
          banners[currentIndex === 1 ? 0 : 1].style.zIndex = '10'
        }, 2500
      )

  };

  // Set the carousel to rotate automatically every 5 seconds
  let autoRotateInterval = setInterval(rotateCarousel, 5000);

  window.hhInterval = autoRotateInterval;

  // Add click listener to toggle the carousel pause/play
  document.querySelector('.Flow-EntireFlow.id-flow_d02099468c5fg664dh31b7cg .Flow-Component.ComponentTag-banner_animated').addEventListener('click', () => {
      if (isPaused) {
          // If paused, continue the carousel rotation
          autoRotateInterval = setInterval(rotateCarousel, 5000);
          window.hhInterval = autoRotateInterval;
          isPaused = false;

          // Move to the next banner immediately
          rotateCarousel();
      } else {
          // Pause the carousel
          clearInterval(autoRotateInterval);
          isPaused = true;
      }
  });
}

