function output() {
    const track = document.querySelector('.ComponentTag-carousel_track');
    const captions = document.querySelectorAll('.ComponentTag-animation_description');

    if (!track || !captions) return;

    let currentIndex = 0;
    const imageWidth = 334;
    const totalImages = 3;

    // Initialize the captions
    captions.forEach((caption, index) => {
        caption.style.opacity = index === 0 ? '1' : '0';
        caption.style.transform = index === 0 ? 'translateY(0)' : 'translateY(16px)';
    });

    function moveCarousel() {
        // Hide the current caption
        if (currentIndex < 2) {
            captions[currentIndex].style.opacity = '0';
        } else {
            window.Savvy.goToNextPage('flow_d02099468c5fg664dh31b7cg');
        }

        currentIndex++;
        if (currentIndex >= totalImages) return;

        // Move carousel
        const offset = -currentIndex * imageWidth;
        track.style.transform = `translateX(${offset}px)`;

        // Show the next caption (small delay to prevent animations from overlapping)
        setTimeout(() => {
            const nextCaption = captions[currentIndex];
            nextCaption.style.opacity = '1';
            nextCaption.style.transform = 'translateY(0)';
        }, 50);

        setTimeout(moveCarousel, 2000);
    }

    // Start animation
    setTimeout(moveCarousel, 2000);
}

function output() {
    const url = window.location.href;
    if (url.includes("app.embeddables")) {
        console.log(url.includes("app.embeddables"))   
