        }, 100);
    }

    const loaderImages = document.querySelectorAll('.ComponentTag-animated_image');
    const descriptionsByMonth = document.querySelectorAll('.ComponentTag-animation_container_months');
    const nextBtn = document.querySelector('.ComponentTag-next_btn_hair_progress_loader');

    if (loaderImages && descriptionsByMonth) {
        loaderImages.forEach(img => {
            img.style.opacity = '0';
            img.style.transition = 'opacity 1s ease';
            img.style.zIndex = '0';
        });

        loaderImages[0].style.opacity = '1';
        loaderImages[0].style.zIndex = '1';

        descriptionsByMonth.forEach(child => {
            child.style.opacity = '0';
            child.style.transform = 'translateY(16px)';
            child.style.transition = 'all 0.5s ease';
        });

        descriptionsByMonth[0].style.opacity = '1';
        descriptionsByMonth[0].style.transform = 'translateY(0)';

        let index = 1;
        const total = loaderImages.length;

        window.hairProgressLoaderInterval = setInterval(() => {
            const prev = (index - 1 + total) % total;

            loaderImages[prev].style.opacity = '0';
            loaderImages[prev].style.zIndex = '0';

            loaderImages[index].style.opacity = '1';
            loaderImages[index].style.zIndex = `${index + 1}`;

            descriptionsByMonth[prev].style.opacity = '0';
            descriptionsByMonth[prev].style.transform = 'translateY(16px)';

            descriptionsByMonth[index].style.opacity = '1';
            descriptionsByMonth[index].style.transform = 'translateY(0)';

            index = (index + 1) % total;
        }, 2000);


        window.hairProgressLoaderTimeout = setTimeout(() => {
            if (nextBtn) {
                nextBtn.style.opacity = '1';
                nextBtn.style.transform = 'translateY(-16px)';
            }
        }, 6000);
    }
}

