	const isDev = window.location.origin.includes('form.dev.happyhead.com');

	const apiKey = userData.is_production_environment
		? 'f8d44ba7-2d6a-4aa6-aabf-811f85f11770'
		: isDev
			? '{{cred_3rime6wfwczk}}'
			: 'secret';

	let url = userData.is_production_environment
		? 'https://api.happyhead.com/middleware/product-recommendation'
		: isDev
			? 'https://api.dev.happyhead.com/middleware/product-recommendation'
			: 'https://api.staging.happyhead.com/middleware/product-recommendation';

	const userPreferredMethodsMap = {
		oral: ['Oral'],
		topical: ['Topical'],
		unsure_no_preference: ['Oral', 'Topical'],
	};

	const options = {
		method: 'POST',
		headers: {
			'Content-Type': 'application/json; charset=utf-8',
			'x-api-key': apiKey,
		},
		body: JSON.stringify({
			dateOfBirth: userData.date_of_birth_formatted,
			userChosenPids: userData.pid_formatted_for_api_request,
			userPreferredMethods: userPreferredMethodsMap[userData.preferred_method_of_medication],
			gender:
				userData.sex_at_birth.charAt(0).toUpperCase() +
				userData.sex_at_birth.slice(1),
		}),
	};

	fetch(url, options)
		.then((response) => {
			if (!response.ok) {
				throw new Error(`Response status: ${response.status}`);
			}
			return response.json();
		})
		.then((data) => {
			// 1. Make the request and get the response (data).
			const femaleUnder50Text = 'women under 50';
			const femaleOver50Text = 'women 50+';

			const productsOptionsMap = [{
				key: 'scalp',
				text: 'Topical<sup>Rx</sup> Solution',
				description: 'Dutasteride & Minoxidil<sup>Rx</sup>',
				sku: 'TOPDUT2-1',
				image_url: 'https://assets.embeddables.com/topical_9104253318867058.png',
				female_age_range_text: femaleOver50Text,
			},
			{
				key: 'capsule',
				text: 'SuperCapsule<sup>TM</sup>',
				description: 'Dutasteride, Minoxidil<sup>Rx</sup> & Vitamin D3',
				sku: 'SUPERCAP-DUT2-1',
				image_url: 'https://assets.embeddables.com/HappyHead_r1_03F_25681_6073964046736036.png',
				female_age_range_text: femaleOver50Text
			},
			{
				key: 'combination',
				text: 'Topical<sup>Rx</sup> Solution + SuperCapsule<sup>TM</sup> Bundle',
				description: 'Dutasteride & Minoxidil<sup>RX</sup>',
				sku: 'TOPDUT2-1/SUPERCAP-DUT2-1',
				image_url: 'https://assets.embeddables.com/HappyHead-2Rx-Bundle_3235002678330572.png',
				female_age_range_text: femaleOver50Text
			},
			{
				key: 'scalp',
				text: 'Minoxidil & Retinoic Acid<sup>Rx</sup>',
				description: 'Topical<sup>Rx</sup> Solution',
				sku: 'TOP-MIN6-1',
				image_url: 'https://assets.embeddables.com/topical_9104253318867058.png',
				female_age_range_text: femaleUnder50Text
			},
			{
				key: 'capsule',
				text: 'Oral<sup>Rx</sup> SuperCapsule<sup>TM</sup>',
				description: 'Spironolactone, Minoxidil<sup>Rx</sup> & Vitamin D3',
				sku: 'SUPERCAP-SPIR-1',
				image_url: 'https://assets.embeddables.com/HappyHead_r1_03F_25681_6073964046736036.png',
				female_age_range_text: femaleUnder50Text
			},
			{
				key: 'combination',
				text: 'Topical<sup>Rx</sup> Solution + Oral<sup>Rx</sup> SuperCapsule<sup>TM</sup> Bundle',
				description: 'Spironolactone & Minoxidil<sup>RX</sup>',
				sku: 'SUPERCAP-SPIR-1/TOP-MIN6-1',
				image_url: 'https://assets.embeddables.com/HappyHead-2Rx-Bundle_3235002678330572.png',
				female_age_range_text: femaleUnder50Text
			}];

			const methodKey = userData.female_under_50 ? 'method_fem' : 'method';
			// console.log('\n\n\n\n\n\n methodKey', methodKey);

			// 2. From the six products, filter the three corresponding to the SKUs that came in the request (filterProductsByResponse):
			const filterProductsByResponse = (data) =>
				data.map(group => {
					const sku = group.length > 1
						? group.map(item => item.sku).join('/')
						: group[0]?.sku;

					return productsOptionsMap.find(product => product.sku === sku);
				})
					.filter(Boolean);

			const productsFilteredByResponse = filterProductsByResponse(data);
			// console.log('\n\n\n\n\n\n productsFilteredByResponse', productsFilteredByResponse);

			// 3. Now, from the three remaining, only keep the one whose key matches the one stored in 'method' (or 'method_fem')
			// console.log('\n\n\n\n\n\n userData[methodKey]', userData[methodKey]);
			const filteredProductBySelectedMethod = productsFilteredByResponse.find(product => product.key === userData[methodKey]);
			// console.log('\n\n\n\n\n\n filteredProductBySelectedMethod', filteredProductBySelectedMethod)

			// 4. Take the SKU of the single resulting product, and look in the initial response for the PID that corresponds to that SKU.
			const productSkuForTheSelectedMethod = filteredProductBySelectedMethod?.sku;
			// console.log('\n\n\n\n\n\n productSkuForTheSelectedMethod', productSkuForTheSelectedMethod);

			const refreshedProductsBySku = data.filter(group => {
				return group.some(product => {
					let sku = '';

					if (productSkuForTheSelectedMethod.includes('/')) {
						sku = productSkuForTheSelectedMethod.split('/')?.[0];
					} else {
						sku = productSkuForTheSelectedMethod;
					}
					// console.log('SKU', sku);

					return product.sku === sku;
				})
			});
			// console.log('\n\n\n\n\n\n refreshedProductsBySku', refreshedProductsBySku);

			const refreshedProductBySelectedMethod = refreshedProductsBySku.find(group =>
				userData[methodKey] === "combination" ? group.length > 1 : group.length === 1
			);

			// console.log('\n\n\n\n\n\n refreshedProductBySelectedMethod', refreshedProductBySelectedMethod);

			let productPid = "";

			if (refreshedProductBySelectedMethod) {
				if (userData[methodKey] === "combination") {
					productPid = refreshedProductBySelectedMethod
						.map(product => product.woocommerceId)
						.join('%2C');
				} else {
					productPid = refreshedProductBySelectedMethod[0].woocommerceId.toString();
				}
			}

			// console.log('\nproductPid', productPid);
			// console.log('product_ids before change', userData.product_ids, '\n');

			const refreshedProductDetails = productsFilteredByResponse
				.filter(product => userData[methodKey] === product.key)
				.map(product => ({
					...product,
					updated_pid: productPid,
					old_pid: userData.product_ids
				}));

			console.log('\n\n\n\n\n\n refreshedProductDetails', refreshedProductDetails[0]);

			context.setUserData({
				product_ids: productPid,
				refreshed_product_dob_not_matching: refreshedProductDetails[0],
				// method_options: productsFilteredByResponse,
			});
		})
		.catch((error) => {
			console.error(error.message);
		});
}

