function output() {
  const input = document.querySelector(".ComponentKey-dob_input_v2 input");
  if (!input) return;

  input.setAttribute("inputmode", "numeric");

  input.addEventListener("input", (e) => {
    // Only digits
    let cleaned = e.target.value.replace(/\D/g, "");

    // Limit to 8 digits max (MMDDYYYY)
    if (cleaned.length > 8) {
      cleaned = cleaned.slice(0, 8);
    }

    // Build MM, DD, YYYY parts
    const mm = cleaned.slice(0, 2);
    const dd = cleaned.slice(2, 4);
    const yyyy = cleaned.slice(4, 8);

    // Format with dashes
    let formatted = "";
    if (cleaned.length >= 5) {
      formatted = `${mm} / ${dd} / ${yyyy}`;
    } else if (cleaned.length >= 3) {
      formatted = `${mm} / ${dd}`;
    } else {
      formatted = mm;
    }

    // Set formatted value
    e.target.value = formatted;
  });
}

