function output({ split_new_year_banner }, { getComponentElement }) {

  if(!split_new_year_banner || !split_new_year_banner === 'variant_1') return;

  const header = getComponentElement('global_header');
  const banner = getComponentElement('new_year_promo');
  if (!header) return;

  // Lock header
  header.style.position = 'fixed';
  header.style.left = '0';
  header.style.right = '0';
  header.style.zIndex = '999';

  function getScroll() {
    // Use visualViewport if available for mobile
    if (window.visualViewport) {
      return window.visualViewport.pageTop || window.visualViewport.offsetTop || 0;
    }
    // fallback for desktop
    return window.pageYOffset || document.documentElement.scrollTop || 0;
  }



  function updateHeader() {
    const scrollTop = getScroll();
    const isMobile = window.innerWidth <= 500;
    const isTablet = window.innerWidth <= 1024;

    const options = {
      root: null, // defaults to the browser viewport
      rootMargin: "0px",
      threshold: 0.0, // callback executes as soon as even one pixel is visible (or not visible)
    };

    const observer = new IntersectionObserver(handleIntersection, options);

    function handleIntersection(entries, observer) {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          // The component is in view (or just entered view)
          header.style.position = 'sticky';
          header.style.top = '0';
          // You can add logic here (e.g., start animations, lazy load data)
        } else {
          // The component is OUT of view (or just left view)
          header.style.position = 'fixed';
          header.style.top = '0';
          // You can add logic here (e.g., stop animations, clean up resources)
        }
      });
    }

    if (banner && isMobile) {
      observer.observe(banner);
      return;
    }

    // Any device: scrolled → stick to top
    if (scrollTop > 0) {
      header.style.top = '0px';
      header.style.transform = 'none';
      header.style.opacity = '1';
      header.style.visibility = 'visible';
      return;
    }

    // At top → restore offsets
    if (isTablet) {
      header.style.top = '180.83px';
    } else {
      header.style.top = '76.99px';
    }

    // Reset visual properties
    header.style.transform = 'none';
    header.style.opacity = '1';
    header.style.visibility = 'visible';
  }

  updateHeader();

  window.addEventListener('scroll', updateHeader, { passive: true });
  window.addEventListener('touchmove', updateHeader, { passive: true });
  window.visualViewport?.addEventListener('scroll', updateHeader, { passive: true });
  window.addEventListener('resize', updateHeader);
}

