function output(userData, { setUserData, getComponentElement }) {
  const hotspots = [
    { key: 'hotspot_1', state: 'is_hotspot_1_active' },
    { key: 'hotspot_2', state: 'is_hotspot_2_active' },
    { key: 'hotspot_3', state: 'is_hotspot_3_active' },
    { key: 'hotspot_4', state: 'is_hotspot_4_active' },
    { key: 'hotspot_5', state: 'is_hotspot_5_active' },
    { key: 'hotspot_6', state: 'is_hotspot_6_active' }
  ];

  const supportsHover = window.matchMedia('(hover: hover)').matches;

  // ✅ Ensure all states exist as top-level properties
  const ensureStatesExist = {};
  hotspots.forEach(h => {
    if (typeof userData[h.state] === "undefined") {
      ensureStatesExist[h.state] = false;
    }
  });

  if (Object.keys(ensureStatesExist).length) {
    setUserData(ensureStatesExist);
  }

  const closeAll = () => {
    const reset = {};
    hotspots.forEach(h => reset[h.state] = false);
    setUserData(reset);
  };

  hotspots.forEach(h => {
    const el = getComponentElement(h.key);
    if (!el) return;

    if (supportsHover) {
      // Desktop
      el.addEventListener('mouseenter', () => {
        closeAll();
        setUserData({
          [h.state]: true
        });
      });

      el.addEventListener('mouseleave', () => {
        setUserData({
          [h.state]: false
        });
      });

    } else {
      // Mobile
      el.addEventListener('click', (e) => {
        e.stopPropagation();

        const isActive = userData[h.state];

        closeAll();

        if (!isActive) {
          setUserData({
            [h.state]: true
          });
        }
      });
    }
  });

  if (!supportsHover) {
    document.addEventListener('click', () => {
      closeAll();
    });
  }


}

