const FLOW_ID = 'flow_d02099468c5fg664dh31b7cg';
const PRP_SUBMITTED_ACTION_ID = '_a9882497878614032';
const FLOW_SELECTOR = `.Flow-EntireFlow.id-${FLOW_ID}`;
const CTA_SELECTOR = '.prp-bundle-pricing-test-cta';
const BIND_DELAYS_MS = [0, 300, 1500];

let navigateLockUntil = 0;
let documentHandler = null;

function getEventElement(event) {
  const raw = event.target;

  if (raw instanceof Element) return raw;

  if (raw && raw.nodeType === Node.TEXT_NODE && raw.parentElement instanceof Element) {
    return raw.parentElement;
  }

  return null;
}

function navigateFromBundlePricingTestCta() {
  if (!window.Savvy) return;
  if (Date.now() < navigateLockUntil) return;

  navigateLockUntil = Date.now() + 1000;

  window.Savvy.triggerAction(FLOW_ID, PRP_SUBMITTED_ACTION_ID);
  window.Savvy.goToNextPage(FLOW_ID);
}

function onBundlePricingTestCtaActivate(event) {
  if (event.type === 'keydown' && event.key !== 'Enter' && event.key !== ' ') return;
  if (event.type === 'pointerup' && event.pointerType === 'mouse' && event.button !== 0) return;

  event.preventDefault();
  event.stopPropagation();
  event.stopImmediatePropagation();

  navigateFromBundlePricingTestCta();
}

function handleDocumentCtaInteraction(event) {
  if (event.type === 'keydown' && event.key !== 'Enter' && event.key !== ' ') return;
  if (event.type === 'pointerup' && event.pointerType === 'mouse' && event.button !== 0) return;

  const target = getEventElement(event);
  if (!target) return;

  const cta = target.closest(CTA_SELECTOR);
  if (!cta || !cta.closest(FLOW_SELECTOR)) return;

  onBundlePricingTestCtaActivate(event);
}

function bindDocumentCtaHandler() {
  if (documentHandler) {
    document.removeEventListener('pointerup', documentHandler, true);
    document.removeEventListener('click', documentHandler, true);
    document.removeEventListener('keydown', documentHandler, true);
  }

  documentHandler = handleDocumentCtaInteraction;

  document.addEventListener('pointerup', documentHandler, true);
  document.addEventListener('click', documentHandler, true);
  document.addEventListener('keydown', documentHandler, true);
}

function bindBundlePricingTestCta(cta) {
  if (!(cta instanceof Element) || cta.dataset.prpBundleCtaBound === '1') return;

  cta.dataset.prpBundleCtaBound = '1';
  cta.addEventListener('pointerup', onBundlePricingTestCtaActivate, true);
  cta.addEventListener('click', onBundlePricingTestCtaActivate, true);
  cta.addEventListener('keydown', onBundlePricingTestCtaActivate, true);
}

function bindAllBundlePricingTestCtas() {
  const flowRoot = document.querySelector(FLOW_SELECTOR);
  if (!flowRoot) return;

  flowRoot.querySelectorAll(CTA_SELECTOR).forEach(bindBundlePricingTestCta);
}

function ensureBundlePricingTestCtaObserver() {
  const flowRoot = document.querySelector(FLOW_SELECTOR);
  if (!flowRoot) return;

  if (window.__prpBundlePricingTestCtaObserver) {
    window.__prpBundlePricingTestCtaObserver.disconnect();
  }

  const observer = new MutationObserver(bindAllBundlePricingTestCtas);
  observer.observe(flowRoot, { childList: true, subtree: true });
  window.__prpBundlePricingTestCtaObserver = observer;
}

function setupBundlePricingTestCtaHandlers() {
  bindDocumentCtaHandler();
  bindAllBundlePricingTestCtas();
  ensureBundlePricingTestCtaObserver();
}

function scheduleBundlePricingTestCtaSetup() {
  window.__prpBundlePricingTestCtaBindTimeouts?.forEach(clearTimeout);
  window.__prpBundlePricingTestCtaBindTimeouts = BIND_DELAYS_MS.map((delayMs) =>
    setTimeout(setupBundlePricingTestCtaHandlers, delayMs)
  );
}

function output() {
  scheduleBundlePricingTestCtaSetup();
}

const FLOW_ID = 'flow_d02099468c5fg664dh31b7cg';
const PRP_PAGE_KEY = 'prp_page_v2';
const PRP_SUBMITTED_ACTION_ID = '_a9882497878614032';
const FLOW_SELECTOR = `.Flow-EntireFlow.id-${FLOW_ID}`;
const CP_ROUTINE_HEADER_SELECTOR = '.prp-v2-card-cp-routine__header';
const CP_ROUTINE_CTA_SELECTOR = '.prp-v2-card-cp-routine__cta';

function isOnPrpPageV2() {
  return window.Savvy?.getUserData(FLOW_ID)?.current_page_key === PRP_PAGE_KEY;
}

let cpRoutineDocumentHandler = null;
let cpRoutineCardChangeHandler = null;

function resolveUpgradeFlags(cta) {
  if (cta.classList.contains('prp-v2-card-topical-only-link')) {
    return { includeDermarollerUpgrade: false, includeCopperPeptideUpgrade: false };
  }

  if (cta.classList.contains('prp-v2-card-cta') && cta.closest('.ElementKey-scalp')) {
    const userData = window.Savvy?.getUserData(FLOW_ID) ?? {};

    if (userData.upgrade_path === 'derm') {
      return { includeDermarollerUpgrade: true, includeCopperPeptideUpgrade: false };
    }
  }

  return { includeDermarollerUpgrade: false, includeCopperPeptideUpgrade: false };
}

function isCardSelected(card) {
  return card?.classList.contains('selected') || card?.hasAttribute('selected');
}

function requiresSelectedCard(cta) {
  return (
    cta.classList.contains('prp-v2-card-topical-only-link') ||
    cta.classList.contains('prp-v2-card-cp-routine__cta') ||
    (cta.classList.contains('prp-v2-card-cta') && Boolean(cta.closest('.ElementKey-scalp')))
  );
}

function getEventElement(event) {
  const raw = event.target;

  if (raw instanceof Element) return raw;

  if (raw && raw.nodeType === Node.TEXT_NODE && raw.parentElement instanceof Element) {
    return raw.parentElement;
  }

  return null;
}

function closeAllCpRoutineDropdowns() {
  document.querySelectorAll(`${FLOW_SELECTOR} .prp-v2-card-cp-routine.is-open`).forEach((dropdown) => {
    dropdown.classList.remove('is-open');
  });
}

function setCpRoutineDropdownOpen(isOpen) {
  window.Savvy?.setUserData(FLOW_ID, { cp_routine_dropdown_open: isOpen });
}

function getScalpCardFromHeader(header) {
  const card = header.closest('.ElementType-OptionButtonCard');
  if (!card?.classList.contains('ElementKey-scalp')) return null;
  return card;
}

function onCpRoutineHeaderActivate(event) {
  if (!isOnPrpPageV2()) return;
  if (event.type === 'keydown' && event.key !== 'Enter' && event.key !== ' ') return;

  const target = getEventElement(event);
  if (!target) return;

  const header = target.closest(CP_ROUTINE_HEADER_SELECTOR);
  if (!header || !header.closest(FLOW_SELECTOR)) return;

  const card = getScalpCardFromHeader(header);
  if (!isCardSelected(card)) return;

  event.preventDefault();
  event.stopPropagation();
  event.stopImmediatePropagation();

  const dropdown = header.closest('.prp-v2-card-cp-routine');
  const userData = window.Savvy?.getUserData(FLOW_ID) ?? {};
  const nextOpen = userData.cp_routine_dropdown_open !== true;

  setCpRoutineDropdownOpen(nextOpen);
  dropdown?.classList.toggle('is-open', nextOpen);
}

function onCpRoutineCtaActivate(event) {
  if (!isOnPrpPageV2()) return;
  if (event.type === 'keydown' && event.key !== 'Enter' && event.key !== ' ') return;

  const target = getEventElement(event);
  if (!target) return;

  const cta = target.closest(CP_ROUTINE_CTA_SELECTOR);
  if (!cta || !cta.closest(FLOW_SELECTOR)) return;

  const card = cta.closest('.ElementType-OptionButtonCard');
  if (!isCardSelected(card)) return;

  event.preventDefault();
  event.stopPropagation();
  event.stopImmediatePropagation();

  proceed({ includeDermarollerUpgrade: false, includeCopperPeptideUpgrade: true });
}

function handleCpRoutineCardChange(event) {
  if (!isOnPrpPageV2()) return;

  const target = getEventElement(event);
  if (!target) return;

  const card = target.closest('.ElementType-OptionButtonCard');
  if (!card?.closest(FLOW_SELECTOR)) return;

  if (!card.classList.contains('ElementKey-scalp')) {
    closeAllCpRoutineDropdowns();
    window.Savvy?.setUserData(FLOW_ID, {
      cp_routine_dropdown_open: false,
      include_copper_peptide_upgrade: false,
    });
  }
}

function resetCpRoutineDropdownState(context) {
  closeAllCpRoutineDropdowns();

  const reset = {
    cp_routine_dropdown_open: false,
    include_copper_peptide_upgrade: false,
  };

  if (context?.setUserData) {
    context.setUserData(reset);
    return;
  }

  window.Savvy?.setUserData(FLOW_ID, reset);
}

function bindCpRoutineDocumentHandlers() {
  if (window.__cpRoutineDropdownBound) return;
  window.__cpRoutineDropdownBound = true;

  cpRoutineDocumentHandler = (event) => {
    onCpRoutineHeaderActivate(event);
    onCpRoutineCtaActivate(event);
  };

  document.addEventListener('click', cpRoutineDocumentHandler, true);
  document.addEventListener('keydown', cpRoutineDocumentHandler, true);

  cpRoutineCardChangeHandler = handleCpRoutineCardChange;
  document.addEventListener('click', cpRoutineCardChangeHandler, true);
}

function proceed({ includeDermarollerUpgrade, includeCopperPeptideUpgrade }) {
  const continueFlow = () => {
    window.Savvy?.triggerAction(FLOW_ID, PRP_SUBMITTED_ACTION_ID);
    window.Savvy?.goToNextPage(FLOW_ID);
  };

  const setData = window.Savvy?.setUserData(FLOW_ID, {
    include_dermaroller_upgrade: includeDermarollerUpgrade,
    include_copper_peptide_upgrade: includeCopperPeptideUpgrade,
  });

  if (setData?.then) {
    setData.then(continueFlow);
    return;
  }

  continueFlow();
}

function output(userData, context) {
  resetCpRoutineDropdownState(context);
  bindCpRoutineDocumentHandlers();

  if (window.__prpV2CardCtaClickBound) return;
  window.__prpV2CardCtaClickBound = true;

  document.addEventListener(
    'click',
    (event) => {
      if (!isOnPrpPageV2()) return;

      const target = event.target instanceof Element ? event.target : event.target?.parentElement;
      const cta = target?.closest('.prp-v2-card-cta, .prp-v2-card-topical-only-link');
      if (!cta?.closest(`.id-${FLOW_ID}`)) return;

      if (cta.classList.contains('prp-v2-card-cp-routine__cta')) return;

      const card = cta.closest('.ElementType-OptionButtonCard');

      if (requiresSelectedCard(cta) && !isCardSelected(card)) {
        return;
      }

      event.stopPropagation();

      proceed(resolveUpgradeFlags(cta));
    },
    true
  );
}

function output(userData, context) {
  const methodKey = userData.female_under_50 ? userData.method_fem : userData.method;

  if (methodKey !== 'scalp') {
    context.setUserData({
      include_dermaroller_upgrade: false,
      include_copper_peptide_upgrade: false,
      cp_routine_dropdown_open: false,
    });

    document.querySelectorAll('.prp-v2-card-cp-routine.is-open').forEach((dropdown) => {
      dropdown.classList.remove('is-open');
    });
  }
}

