function result({ date_of_birth_formatted }) {
  // Ensure the date_of_birth is in the proper format (YYYY-MM-DD)
  const birthDate = new Date(date_of_birth_formatted);

  // Get the current date
  const currentDate = new Date();

  // Calculate the difference in years
  let age = currentDate.getFullYear() - birthDate.getFullYear();

  // Check if the current date has passed the user's birthday this year
  const monthDifference = currentDate.getMonth() - birthDate.getMonth();
  const dayDifference = currentDate.getDate() - birthDate.getDate();

  // If the birthday hasn't occurred yet this year, subtract one year from the calculated age
  if (monthDifference < 0 || (monthDifference === 0 && dayDifference < 0)) {
    age--;
  }

  return age;
}

