  }

  function getAllWooIds(options) {
    const allIds = [];

    options.forEach(option => {
      if (typeof option.woocommerceId === 'number') {
        allIds.push(option.woocommerceId);
      } else if (typeof option.woocommerceId === 'string') {
        let wooIdStr = option.woocommerceId;

        if (wooIdStr.includes('%2C')) {
          wooIdStr = decodeURIComponent(wooIdStr.replace(/%2C/g, '-'));
          allIds.push(wooIdStr);
        } else {
          const ids = decodeURIComponent(wooIdStr).split(',');
          ids.forEach(id => {
            const parsed = Number(id);
            allIds.push(isNaN(parsed) ? id : parsed);
          });
        }
      }
    });

    return allIds;
  }

  return getAllWooIds(method_options);
}

