function result() {
  const currentUrl = window.location.href;
  const url = new URL(currentUrl);
  const searchParams = url.searchParams;

  const consultParam = searchParams.get("consult");
  const consult = consultParam === "true";

  if (consult) {
    const isProduction = window.location.hostname.includes("form.happyhead.com");
    const pid = searchParams.get("pid");

    if (!pid) return false;

    const pidArray = pid.split(",").map(p => p.trim()).sort();

    const validPairsProd = [
      ["5016601", "5016643"],
      ["5016669", "5016675"]
    ];
    const validPairsDev = [
      ["950062", "950064"],
      ["950066", "950068"]
    ];

    const validPairs = isProduction ? validPairsProd : validPairsDev;

    const validPids = new Set(validPairs.flat());

    if (!pidArray.every(p => validPids.has(p))) {
      return false;
    }

    const isValidPair = validPairs.some(pair => {
      const sortedPair = pair.slice().sort();
      return pidArray.join(",") === sortedPair.join(",");
    });

    if (isValidPair) return true;

    if (pidArray.length === 1 && validPids.has(pidArray[0])) {
      return true;
    }

    return false;
  }

  return false;
}

